const state = getWorkflowStaticData('global');
const now = new Date();
const defaultLookbackMinutes = 20;
const since = state.lastPollAt ? new Date(state.lastPollAt) : new Date(now.getTime() - defaultLookbackMinutes * 60 * 1000);
state.lastPollAt = now.toISOString();
return [{ json: {
  since: since.toISOString(),
  inboxFolderId: $env.OUTLOOK_INBOX_FOLDER_ID || 'inbox',
  sentFolderId: $env.OUTLOOK_SENT_FOLDER_ID || 'sentitems'
}}];

const rows = [];
for (const item of items) {
  const m = item.json;
  const subject = (m.subject || '').trim();
  const body = ((m.bodyPreview || '') + ' ' + (m.body?.content || '')).toLowerCase();
  const to = (m.toRecipients || []).map(r => r?.emailAddress?.address).filter(Boolean).join('; ');
  const from = m.from?.emailAddress?.address || '';
  const isAuto = /(noreply|do-not-reply|mailer-daemon|out of office|automatiskt svar)/i.test(subject + ' ' + from);
  if (isAuto) continue;
  const hasQuestion = /[?]|kan du|kan ni|återkoppla|behöver|när kan|vill du|vill ni/i.test(subject + ' ' + body);
  if (!hasQuestion) continue;
  const isFortnox = /(fortnox|offert|quote)/i.test(subject + ' ' + body);
  rows.push({json:{
    external_message_id: m.id || '',
    conversation_id: m.conversationId || '',
    direction: 'outgoing',
    case_type: isFortnox ? 'fortnox_offert' : 'question_out',
    status: 'waiting_customer',
    customer_email: to,
    owner_email: from,
    subject,
    question_excerpt: (m.bodyPreview || '').slice(0,600),
    sent_at: m.sentDateTime || null,
    received_at: null,
    answered_at: null,
    source_system: 'office365_graph'
  }});
}
return rows;

const rows = [];
for (const item of items) {
  const m = item.json;
  const subject = (m.subject || '').trim();
  const body = ((m.bodyPreview || '') + ' ' + (m.body?.content || '')).toLowerCase();
  const from = m.from?.emailAddress?.address || '';
  const isAuto = /(noreply|do-not-reply|mailer-daemon|out of office|automatiskt svar)/i.test(subject + ' ' + from);
  if (isAuto) continue;
  const hasQuestion = /[?]|kan du|kan ni|återkoppla|behöver|när kan|vill du|vill ni/i.test(subject + ' ' + body);
  rows.push({json:{
    external_message_id: m.id || '',
    conversation_id: m.conversationId || '',
    direction: 'incoming',
    case_type: hasQuestion ? 'question_in' : 'reply_in',
    status: hasQuestion ? 'waiting_me' : 'answered_customer',
    customer_email: from,
    owner_email: '',
    subject,
    question_excerpt: (m.bodyPreview || '').slice(0,600),
    sent_at: null,
    received_at: m.receivedDateTime || null,
    answered_at: null,
    source_system: 'office365_graph'
  }});
}
return rows;

const state = getWorkflowStaticData('global');
state.lastLunchSummaryDate = state.lastLunchSummaryDate || '';
const now = new Date();
const today = now.toISOString().slice(0,10);
const should = now.getHours() === 12 && state.lastLunchSummaryDate !== today;
if (should) state.lastLunchSummaryDate = today;
return [{json:{shouldSendLunch: should}}];

const rows = items.map(i => i.json);
const waitingCustomer = rows.filter(r => r.status === 'waiting_customer');
const waitingMe = rows.filter(r => r.status === 'waiting_me');
const lines = [];
lines.push(`Lunchrapport ${new Date().toISOString().slice(0,10)}`);
lines.push('');
lines.push('Jag väntar på svar från kund:');
if (!waitingCustomer.length) lines.push('- Inga öppna ärenden.');
for (const r of waitingCustomer) lines.push(`- ${r.customer_email || '(okänd)'} | ${r.subject || '(utan ämne)'} | ${r.case_type}`);
lines.push('');
lines.push('Kunder väntar på svar från mig:');
if (!waitingMe.length) lines.push('- Inga öppna ärenden.');
for (const r of waitingMe) lines.push(`- ${r.customer_email || '(okänd)'} | ${r.subject || '(utan ämne)'} | ${r.case_type}`);
return [{json:{body: lines.join('\n')}}];
